(function(){
  var G=Arena.Game, fail=[];
  var rep=Arena.Render.animBakeReport;
  if(!rep) return {assert:false, fail:['no se horneó nada: Arena.Render.animBakeReport no existe']};
  if(rep.clips<rep.pedidos) fail.push('faltan clips: '+rep.faltan.join(','));
  if(rep.bones!==17) fail.push('el rig no declara 17 huesos');

  var p=G.world.getPlayer(), v=G.renderer.visuals[p.id];
  if(!v||!v.rigBones) return {assert:false, fail:['sin rig vivo']};
  var lib=v.handle&&null;
  var map=(v.animLib&&v.animLib.map)||null;
  if(!map) fail.push('el personaje no tiene biblioteca horneada');
  else {
    /* EL DEFECTO RAÍZ: LeftUpperArm del Elfo está en x<0, que es el lado
       DERECHO. Le tiene que tocar la fuente _r. Si vuelve a emparejarse con
       _l, el espejo ha vuelto. */
    if(map.LeftUpperArm!=='upperarm_r') fail.push('espejo: LeftUpperArm←'+map.LeftUpperArm);
    if(map.RightUpperArm!=='upperarm_l') fail.push('espejo: RightUpperArm←'+map.RightUpperArm);
    if(map.LeftFoot!=='foot_r') fail.push('espejo: LeftFoot←'+map.LeftFoot);
  }

  function foto(){
    var o={}; v.root.updateMatrixWorld(true);
    for(var n in v.rigBones){ var q=v.rigBones[n].quaternion;
      o[n]=[q.x,q.y,q.z,q.w]; }
    return o;
  }
  function paso(n){ for(var i=0;i<n;i++){ G.world.stepSeconds(1/30); G.renderer.syncVisuals(1/30);} G.renderer.render(1,1/30); }

  G._running=false;
  p.pos.x=0; p.pos.z=0; p.yaw=0; p.alive=true;
  paso(20);
  var quieto=foto();

  /* Sin NaN y normalizados. */
  for(var n in quieto){ var q=quieto[n];
    var L=Math.sqrt(q[0]*q[0]+q[1]*q[1]+q[2]*q[2]+q[3]*q[3]);
    if(!isFinite(L)) fail.push('NaN en '+n);
    else if(Math.abs(L-1)>0.01) fail.push(n+' sin normalizar ('+L.toFixed(4)+')');
  }

  /* NADA DE T-POSE. En reposo el brazo del Elfo no puede quedar horizontal.
     Se mide la posición mundial de la mano respecto al hombro. */
  function brazoHoriz(lado){
    var h=new THREE_V.Vector3(), m=new THREE_V.Vector3();
    v.rigBones[lado+'UpperArm'].getWorldPosition(h);
    v.rigBones[lado+'Hand'].getWorldPosition(m);
    var dx=m.x-h.x, dy=m.y-h.y, dz=m.z-h.z;
    var L=Math.sqrt(dx*dx+dy*dy+dz*dz)||1;
    return Math.abs(dy/L);   /* 1 = colgando, 0 = horizontal */
  }
  window.THREE_V={Vector3:function(){this.x=0;this.y=0;this.z=0;}};
  function mundo(b){ var e=v.rigBones[b].matrixWorld.elements; return [e[12],e[13],e[14]]; }
  function vertical(lado){
    var h=mundo(lado+'UpperArm'), m=mundo(lado+'Hand');
    var dx=m[0]-h[0],dy=m[1]-h[1],dz=m[2]-h[2];
    var L=Math.sqrt(dx*dx+dy*dy+dz*dz)||1; return -dy/L;
  }
  var vi=vertical('Left'), vd=vertical('Right');
  if(vi<0.45) fail.push('brazo izq casi horizontal en idle: T-pose ('+vi.toFixed(2)+')');
  if(vd<0.45) fail.push('brazo der casi horizontal en idle: T-pose ('+vd.toFixed(2)+')');

  /* El clip tiene que MOVER el esqueleto: si dos fotogramas de idle son
     idénticos, el mixer no está corriendo. */
  paso(6); var luego=foto();
  var mov=0;
  for(var n2 in quieto){ var a=quieto[n2], b=luego[n2];
    mov+=Math.abs(a[0]-b[0])+Math.abs(a[1]-b[1])+Math.abs(a[2]-b[2])+Math.abs(a[3]-b[3]); }
  if(mov<1e-4) fail.push('el esqueleto no se mueve en idle: el mixer no corre');

  /* Andando, las piernas tienen que trabajar. */
  for(var k=0;k<24;k++){ p.pos.z+=0.06; G.world.stepSeconds(1/30); G.renderer.syncVisuals(1/30); }
  G.renderer.render(1,1/30);
  var and1=foto();
  for(var k2=0;k2<4;k2++){ p.pos.z+=0.06; G.world.stepSeconds(1/30); G.renderer.syncVisuals(1/30); }
  G.renderer.render(1,1/30);
  var and2=foto();
  var pierna=0;
  ['LeftUpperLeg','RightUpperLeg','LeftLowerLeg','RightLowerLeg'].forEach(function(n3){
    var a=and1[n3],b=and2[n3];
    pierna+=Math.abs(a[0]-b[0])+Math.abs(a[1]-b[1])+Math.abs(a[2]-b[2])+Math.abs(a[3]-b[3]);
  });
  if(pierna<0.005) fail.push('las piernas no se mueven al andar ('+pierna.toFixed(5)+')');

  return {assert:!fail.length, fail:fail.slice(0,10),
    horneado:rep.clips+'/'+rep.pedidos+' clips en '+rep.bakeMs+' ms',
    brazoVertical:[vi.toFixed(2),vd.toFixed(2)], movIdle:mov.toFixed(4), movPierna:pierna.toFixed(4)};
})()
